verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error("HYG-139: "+m);process.exit(1)}
const files=fs.readdirSync("supabase/migrations").filter((f)=>/^\d{14}_.*\.sql$/.test(f)).sort()
if(files.length<500)fail("only "+files.length+" migrations found; the probe is reading the wrong tree")
const sql=files.map((f)=>fs.readFileSync("supabase/migrations/"+f,"utf8").replace(/--.*$/gm," ")).join("\n;\n")
const lastAt=(re)=>{let i=-1;for(const m of sql.matchAll(re))i=m.index;return i}
const body=(re)=>{const i=lastAt(re);if(i<0)return null;const s=sql.slice(i);const a=s.indexOf("$$");const b=s.indexOf("$$",a+2);return s.slice(0,b)}
const T=/create trigger conversation_participants_one_to_one\s+before insert or update of conversation_id, profile_id on public\.conversation_participants\s+for each row execute function public\.enforce_conversation_one_to_one\(\)/gi
const tAt=lastAt(T)
if(tAt<0)fail("no migration attaches a one-to-one trigger to conversation_participants, so a third person can be added to a direct message")
if(lastAt(/drop trigger (if exists )?conversation_participants_one_to_one/gi)>tAt)fail("a later migration drops the one-to-one trigger")
const F=body(/create (or replace )?function public\.enforce_conversation_one_to_one\(\)/gi)
if(!F)fail("the trigger function public.enforce_conversation_one_to_one is never defined")
if(lastAt(/drop function (if exists )?public\.enforce_conversation_one_to_one/gi)>lastAt(/create (or replace )?function public\.enforce_conversation_one_to_one\(\)/gi))fail("a later migration drops the one-to-one trigger function")
if(!/for no key update/i.test(F))fail("the trigger counts without locking the conversation, so two concurrent inserts can both see one participant and land three")
if(!/v_others\s*>=\s*2/.test(F)||!/conversation_is_one_to_one/.test(F))fail("the trigger does not refuse a third participant")
if(!/migrated_to_room_id/.test(F)||!/conversation_migrated_to_room/.test(F))fail("the trigger lets a conversation that moved to a room take a new participant")
const live=new Map()
for(const m of sql.matchAll(/\b(create|drop)\s+policy\s+(if exists\s+)?"([^"]+)"\s+on\s+(public\.)?stewardships\b([^;]*)/gi)){if(m[1].toLowerCase()==="drop")live.delete(m[3]);else live.set(m[3],m[5])}
const pols=[...live.entries()]
const cmd=(t)=>((/\bfor\s+(select|insert|update|delete|all)\b/i.exec(t)||[])[1]||"all").toLowerCase()
const writes=pols.filter(([,t])=>cmd(t)!=="select")
if(writes.length)fail("stewardships has a write policy ("+writes.map(([n])=>n).join(", ")+"), so the co-steward read is no longer read only")
const reads=pols.filter(([,t])=>cmd(t)==="select")
if(reads.length!==1)fail("stewardships has "+reads.length+" permissive read policies, not one")
const R=reads[0][1]
if(!/private\.leads_scope\(\s*scope_type\s*,\s*scope_id\s*\)/i.test(R))fail("the stewardships read policy has no scope-leader arm, so a leader still cannot read their co-stewards")
if(!/auth_user_id\s*=\s*\(select auth\.uid\(\)\)/i.test(R)||!/get_my_web_role\(\)\)?\s*in\s*\(\x27admin\x27,\s*\x27janitor\x27\)/i.test(R))fail("the stewardships read policy lost its own-edge or staff arm")
if(!/\bto\s+authenticated\b/i.test(R))fail("the stewardships read policy is not limited to signed-in callers")
const L=body(/create (or replace )?function private\.leads_scope\(p_scope_type text, p_scope_id uuid\)/gi)
if(!L)fail("private.leads_scope is never defined")
if(lastAt(/drop function (if exists )?private\.leads_scope/gi)>lastAt(/create (or replace )?function private\.leads_scope/gi))fail("a later migration drops private.leads_scope")
if(!/security definer/i.test(L))fail("private.leads_scope is not SECURITY DEFINER, so the policy re-enters stewardships RLS (42P17)")
if(!/s\.state\s*=\s*\x27active\x27/.test(L))fail("a suspended edge counts as leadership")
for(const c of["host_id","guide_id","mentor_id"])if(!L.includes(c))fail("private.leads_scope ignores the leader column "+c)
const tp="supabase/tests/conversation_one_to_one_and_co_steward_read.test.sql"
if(!fs.existsSync(tp))fail(tp+" is gone, so nothing proves the rule against a real database")
const P=fs.readFileSync(tp,"utf8").replace(/--.*$/gm," ")
const plan=+((/select plan\((\d+)\)/.exec(P)||[])[1]||0)
const n=(P.match(/^select (is|lives_ok|throws_ok|results_eq|is_empty)\(/gm)||[]).length
if(!plan||plan!==n)fail("the pgTAP file plans "+plan+" but asserts "+n)
for(const k of["conversation_is_one_to_one","conversation_migrated_to_room","private.leads_scope","\x2723505\x27"])if(!P.includes(k))fail("the pgTAP file never asserts "+k)
if(!/^enforce_conversation_one_to_one\s+internal\s*$/m.test(fs.readFileSync("scripts/function-grants.txt","utf8")))fail("scripts/function-grants.txt does not declare the trigger function internal")
console.log("ok: a third participant and a migrated conversation are refused by a locking trigger, the one stewardships read policy adds the scope-leader arm through a SECURITY DEFINER helper and stays read only, and "+plan+" pgTAP assertions cover both")'
